namespace sv_dc6cb61bc6c24616b74c8aa6d50b438c.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_dc6cb61bc6c24616b74c8aa6d50b438c.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <!-- Step Indicator Bar -->
    <div class="step-indicator">
        @for (int i = 0; i < stepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < currentStep)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@stepNames[stepIndex]</div>
            </div>
            @if (i < stepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < currentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!isSubmitted)
    {
        <!-- Step 1: Personal Info -->
        @if (currentStep == 0)
        {
            <div class="form-step">
                <h2>Personal Information</h2>

                <div class="form-group">
                    <label for="fullName">Full Name *</label>
                    <input id="fullName" type="text" @bind="fullName" class="form-control" />
                    @if (errors.ContainsKey("fullName"))
                    {
                        <span class="error">@errors["fullName"]</span>
                    }
                </div>

                <div class="form-group">
                    <label for="email">Email *</label>
                    <input id="email" type="email" @bind="email" class="form-control" />
                    @if (errors.ContainsKey("email"))
                    {
                        <span class="error">@errors["email"]</span>
                    }
                </div>

                <div class="form-group">
                    <label for="phone">Phone *</label>
                    <input id="phone" type="tel" @bind="phone" class="form-control" />
                    @if (errors.ContainsKey("phone"))
                    {
                        <span class="error">@errors["phone"]</span>
                    }
                </div>

                <div class="form-group">
                    <label for="address">Address *</label>
                    <input id="address" type="text" @bind="address" class="form-control" />
                    @if (errors.ContainsKey("address"))
                    {
                        <span class="error">@errors["address"]</span>
                    }
                </div>

                <div class="form-buttons">
                    <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@isValidating">
                        @if (isValidating)
                        {
                            <span>Validating...</span>
                        }
                        else
                        {
                            <span>Next</span>
                        }
                    </button>
                </div>
            </div>
        }

        <!-- Step 2: Work History -->
        @if (currentStep == 1)
        {
            <div class="form-step">
                <h2>Work History</h2>

                @for (int i = 0; i < workEntries.Count; i++)
                {
                    var index = i;
                    <div class="work-entry-card">
                        <div class="work-entry-header">
                            <h3>Position @(index + 1)</h3>
                            @if (workEntries.Count > 1)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>

                        <div class="form-group">
                            <label>Company Name *</label>
                            <input type="text" @bind="workEntries[index].Company" class="form-control" />
                        </div>

                        <div class="form-group">
                            <label>Job Title *</label>
                            <input type="text" @bind="workEntries[index].Title" class="form-control" />
                        </div>

                        <div class="form-row">
                            <div class="form-group">
                                <label>Start Date *</label>
                                <input type="date" @bind="workEntries[index].StartDate" class="form-control" />
                            </div>

                            <div class="form-group">
                                <label>End Date</label>
                                <input type="date" @bind="workEntries[index].EndDate" class="form-control"
                                       disabled="@workEntries[index].IsCurrent" />
                                <label class="checkbox-label">
                                    <input type="checkbox" @bind="workEntries[index].IsCurrent" />
                                    Currently working here
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label>Description</label>
                            <textarea @bind="workEntries[index].Description" class="form-control" rows="3"></textarea>
                        </div>
                    </div>
                }

                @if (errors.ContainsKey("work"))
                {
                    <span class="error">@errors["work"]</span>
                }

                <button class="btn btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
                </div>
            </div>
        }

        <!-- Step 3: References -->
        @if (currentStep == 2)
        {
            <div class="form-step">
                <h2>References</h2>

                @for (int i = 0; i < references.Count; i++)
                {
                    var index = i;
                    <div class="reference-card">
                        <div class="work-entry-header">
                            <h3>Reference @(index + 1)</h3>
                            @if (references.Count > 2)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>

                        <div class="form-group">
                            <label>Name *</label>
                            <input type="text" @bind="references[index].Name" class="form-control" />
                        </div>

                        <div class="form-group">
                            <label>Relationship *</label>
                            <input type="text" @bind="references[index].Relationship" class="form-control" />
                        </div>

                        <div class="form-row">
                            <div class="form-group">
                                <label>Email *</label>
                                <input type="email" @bind="references[index].Email" class="form-control" />
                            </div>

                            <div class="form-group">
                                <label>Phone *</label>
                                <input type="tel" @bind="references[index].Phone" class="form-control" />
                            </div>
                        </div>
                    </div>
                }

                @if (errors.ContainsKey("references"))
                {
                    <span class="error">@errors["references"]</span>
                }

                @if (references.Count < 3)
                {
                    <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
                }

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
                </div>
            </div>
        }

        <!-- Step 4: Cover Letter -->
        @if (currentStep == 3)
        {
            <div class="form-step">
                <h2>Cover Letter</h2>

                <div class="form-group">
                    <label for="coverLetter">Write your cover letter</label>
                    <textarea id="coverLetter" @bind="coverLetter" @bind:event="oninput"
                              class="form-control cover-letter-input" rows="12"
                              maxlength="2000"></textarea>
                    <div class="character-count">@coverLetter.Length / 2000 characters</div>
                </div>

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
                </div>
            </div>
        }

        <!-- Step 5: Review & Submit -->
        @if (currentStep == 4)
        {
            <div class="form-step">
                <h2>Review & Submit</h2>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <a href="javascript:void(0)" @onclick='() => NavigateToStep(0)'>Edit</a>
                    </div>
                    <dl>
                        <dt>Full Name</dt><dd>@fullName</dd>
                        <dt>Email</dt><dd>@email</dd>
                        <dt>Phone</dt><dd>@phone</dd>
                        <dt>Address</dt><dd>@address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <a href="javascript:void(0)" @onclick='() => NavigateToStep(1)'>Edit</a>
                    </div>
                    @foreach (var entry in workEntries)
                    {
                        <div class="review-work-entry">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                            <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p>@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <a href="javascript:void(0)" @onclick='() => NavigateToStep(2)'>Edit</a>
                    </div>
                    @foreach (var reference in references)
                    {
                        <div class="review-reference">
                            <strong>@reference.Name</strong> (@reference.Relationship)<br />
                            <span>@reference.Email | @reference.Phone</span>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <a href="javascript:void(0)" @onclick='() => NavigateToStep(3)'>Edit</a>
                    </div>
                    <p class="cover-letter-preview">@coverLetter</p>
                </div>

                @if (errors.ContainsKey("submit"))
                {
                    <div class="error">@errors["submit"]</div>
                }

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary btn-submit" @onclick="SubmitApplication" disabled="@isSubmitting">
                        @if (isSubmitting)
                        {
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
            </div>
        }
    }
    else
    {
        <!-- Confirmation -->
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted Successfully!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <div class="application-id">@applicationId</div>
            <p>Please save this ID for your records.</p>
        </div>
    }
</div>

<style>
    .application-form {
        max-width: 800px;
        margin: 0 auto;
        padding: 2rem;
    }

    .step-indicator {
        display: flex;
        align-items: center;
        justify-content: center;
        margin-bottom: 2rem;
        padding: 1rem 0;
    }

    .step {
        display: flex;
        flex-direction: column;
        align-items: center;
        cursor: default;
        opacity: 0.4;
        transition: opacity 0.2s;
    }

    .step.active {
        opacity: 1;
    }

    .step.completed {
        opacity: 1;
        cursor: pointer;
    }

    .step-circle {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        background: #e0e0e0;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: bold;
        font-size: 0.9rem;
        margin-bottom: 0.4rem;
    }

    .step.active .step-circle {
        background: #1976d2;
        color: white;
    }

    .step.completed .step-circle {
        background: #4caf50;
        color: white;
    }

    .step-label {
        font-size: 0.75rem;
        text-align: center;
        max-width: 80px;
    }

    .step-connector {
        flex: 1;
        height: 2px;
        background: #e0e0e0;
        margin: 0 0.5rem;
        margin-bottom: 1.5rem;
    }

    .step-connector.completed {
        background: #4caf50;
    }

    .form-step {
        background: #fff;
        border: 1px solid #e0e0e0;
        border-radius: 8px;
        padding: 2rem;
    }

    .form-group {
        margin-bottom: 1rem;
    }

    .form-group label {
        display: block;
        font-weight: 600;
        margin-bottom: 0.3rem;
        font-size: 0.9rem;
    }

    .form-control {
        width: 100%;
        padding: 0.5rem 0.75rem;
        border: 1px solid #ccc;
        border-radius: 4px;
        font-size: 1rem;
        box-sizing: border-box;
    }

    .form-control:focus {
        outline: none;
        border-color: #1976d2;
        box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.2);
    }

    .form-row {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 1rem;
    }

    .form-buttons {
        display: flex;
        justify-content: space-between;
        margin-top: 1.5rem;
        padding-top: 1rem;
        border-top: 1px solid #e0e0e0;
    }

    .btn {
        padding: 0.6rem 1.5rem;
        border: none;
        border-radius: 4px;
        font-size: 1rem;
        cursor: pointer;
        transition: background 0.2s;
    }

    .btn:disabled {
        opacity: 0.6;
        cursor: not-allowed;
    }

    .btn-primary {
        background: #1976d2;
        color: white;
        margin-left: auto;
    }

    .btn-primary:hover:not(:disabled) {
        background: #1565c0;
    }

    .btn-outline {
        background: transparent;
        border: 1px solid #ccc;
        color: #333;
    }

    .btn-outline:hover {
        background: #f5f5f5;
    }

    .btn-secondary {
        background: #f5f5f5;
        border: 1px solid #ccc;
        color: #333;
        margin-bottom: 1rem;
    }

    .btn-secondary:hover {
        background: #e8e8e8;
    }

    .btn-danger {
        background: #e53935;
        color: white;
    }

    .btn-sm {
        padding: 0.3rem 0.8rem;
        font-size: 0.85rem;
    }

    .btn-submit {
        padding: 0.75rem 2rem;
        font-size: 1.1rem;
    }

    .error {
        color: #e53935;
        font-size: 0.85rem;
        margin-top: 0.25rem;
        display: block;
    }

    .work-entry-card, .reference-card {
        border: 1px solid #e0e0e0;
        border-radius: 6px;
        padding: 1.25rem;
        margin-bottom: 1rem;
        background: #fafafa;
    }

    .work-entry-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 1rem;
    }

    .work-entry-header h3 {
        margin: 0;
        font-size: 1rem;
    }

    .checkbox-label {
        display: inline-flex !important;
        align-items: center;
        gap: 0.4rem;
        font-weight: normal !important;
        margin-top: 0.4rem;
        font-size: 0.85rem;
    }

    .checkbox-label input[type="checkbox"] {
        width: auto;
    }

    .cover-letter-input {
        resize: vertical;
        min-height: 200px;
    }

    .character-count {
        text-align: right;
        font-size: 0.85rem;
        color: #666;
        margin-top: 0.3rem;
    }

    .review-section {
        border: 1px solid #e0e0e0;
        border-radius: 6px;
        padding: 1.25rem;
        margin-bottom: 1rem;
    }

    .review-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 0.75rem;
    }

    .review-header h3 {
        margin: 0;
    }

    .review-header a {
        color: #1976d2;
        text-decoration: none;
        font-size: 0.9rem;
    }

    .review-header a:hover {
        text-decoration: underline;
    }

    .review-section dl {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.3rem 1rem;
        margin: 0;
    }

    .review-section dt {
        font-weight: 600;
        color: #555;
    }

    .review-section dd {
        margin: 0;
    }

    .review-work-entry, .review-reference {
        padding: 0.5rem 0;
        border-bottom: 1px solid #eee;
    }

    .review-work-entry:last-child, .review-reference:last-child {
        border-bottom: none;
    }

    .cover-letter-preview {
        white-space: pre-wrap;
        background: #f9f9f9;
        padding: 1rem;
        border-radius: 4px;
        margin: 0;
    }

    .confirmation {
        text-align: center;
        padding: 3rem 2rem;
        background: #fff;
        border: 1px solid #e0e0e0;
        border-radius: 8px;
    }

    .confirmation-icon {
        width: 64px;
        height: 64px;
        border-radius: 50%;
        background: #4caf50;
        color: white;
        font-size: 2rem;
        display: flex;
        align-items: center;
        justify-content: center;
        margin: 0 auto 1rem;
    }

    .application-id {
        font-size: 1.5rem;
        font-weight: bold;
        color: #1976d2;
        margin: 1rem 0;
    }
</style>

@code {
    private readonly string[] stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private int currentStep = 0;
    private bool isSubmitted = false;
    private int applicationId = 0;
    private bool isValidating = false;
    private bool isSubmitting = false;
    private Dictionary<string, string> errors = new();

    // Step 1: Personal Info
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2: Work History
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string coverLetter = "";

    private string GetStepClass(int step)
    {
        if (step == currentStep) return "active";
        if (step < currentStep) return "completed";
        return "";
    }

    private void NavigateToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(fullName))
            errors["fullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(email))
            errors["email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(phone))
            errors["phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(address))
            errors["address"] = "Address is required.";

        if (errors.Count > 0) return;

        isValidating = true;
        StateHasChanged();

        try
        {
            var isEmailValid = await ApplicationService.ValidateEmailAsync(email);
            if (!isEmailValid)
            {
                errors["email"] = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        currentStep = 1;
    }

    private void NextFromWorkHistory()
    {
        errors.Clear();

        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == default)
            {
                errors["work"] = "Each position requires at least a company name, job title, and start date.";
                return;
            }
        }

        currentStep = 2;
    }

    private void NextFromReferences()
    {
        errors.Clear();

        foreach (var reference in references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship)
                || string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                errors["references"] = "All fields are required for each reference.";
                return;
            }
        }

        currentStep = 3;
    }

    private void NextFromCoverLetter()
    {
        currentStep = 4;
    }

    private void PreviousStep()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void AddWorkEntry()
    {
        workEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        errors.Clear();
        isSubmitting = true;
        StateHasChanged();

        try
        {
            var personal = new PersonalInfo(fullName, email, phone, address);
            var work = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? "")
            ).ToList());
            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            errors["submit"] = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

namespace sv_dc6cb61bc6c24616b74c8aa6d50b438c.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_dc6cb61bc6c24616b74c8aa6d50b438c.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <!-- Step Indicator Bar -->
    <div class="step-indicator">
        @for (int i = 0; i < stepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < currentStep)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@stepNames[stepIndex]</div>
            </div>
            @if (i < stepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < currentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!isSubmitted)
    {
        <!-- Step 1: Personal Info -->
        @if (currentStep == 0)
        {
            <div class="form-step">
                <h2>Personal Information</h2>

                <div class="form-group">
                    <label for="fullName">Full Name *</label>
                    <input id="fullName" type="text" @bind="fullName" class="form-control" />
                    @if (errors.ContainsKey("fullName"))
                    {
                        <span class="error">@errors["fullName"]</span>
                    }
                </div>

                <div class="form-group">
                    <label for="email">Email *</label>
                    <input id="email" type="email" @bind="email" class="form-control" />
                    @if (errors.ContainsKey("email"))
                    {
                        <span class="error">@errors["email"]</span>
                    }
                </div>

                <div class="form-group">
                    <label for="phone">Phone *</label>
                    <input id="phone" type="tel" @bind="phone" class="form-control" />
                    @if (errors.ContainsKey("phone"))
                    {
                        <span class="error">@errors["phone"]</span>
                    }
                </div>

                <div class="form-group">
                    <label for="address">Address *</label>
                    <input id="address" type="text" @bind="address" class="form-control" />
                    @if (errors.ContainsKey("address"))
                    {
                        <span class="error">@errors["address"]</span>
                    }
                </div>

                <div class="form-buttons">
                    <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@isValidating">
                        @if (isValidating)
                        {
                            <span>Validating...</span>
                        }
                        else
                        {
                            <span>Next</span>
                        }
                    </button>
                </div>
            </div>
        }

        <!-- Step 2: Work History -->
        @if (currentStep == 1)
        {
            <div class="form-step">
                <h2>Work History</h2>

                @for (int i = 0; i < workEntries.Count; i++)
                {
                    var index = i;
                    <div class="work-entry-card">
                        <div class="work-entry-header">
                            <h3>Position @(index + 1)</h3>
                            @if (workEntries.Count > 1)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>

                        <div class="form-group">
                            <label>Company Name *</label>
                            <input type="text" @bind="workEntries[index].Company" class="form-control" />
                        </div>

                        <div class="form-group">
                            <label>Job Title *</label>
                            <input type="text" @bind="workEntries[index].Title" class="form-control" />
                        </div>

                        <div class="form-row">
                            <div class="form-group">
                                <label>Start Date *</label>
                                <input type="date" @bind="workEntries[index].StartDate" class="form-control" />
                            </div>

                            <div class="form-group">
                                <label>End Date</label>
                                <input type="date" @bind="workEntries[index].EndDate" class="form-control"
                                       disabled="@workEntries[index].IsCurrent" />
                                <label class="checkbox-label">
                                    <input type="checkbox" @bind="workEntries[index].IsCurrent" />
                                    Currently working here
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label>Description</label>
                            <textarea @bind="workEntries[index].Description" class="form-control" rows="3"></textarea>
                        </div>
                    </div>
                }

                @if (errors.ContainsKey("work"))
                {
                    <span class="error">@errors["work"]</span>
                }

                <button class="btn btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
                </div>
            </div>
        }

        <!-- Step 3: References -->
        @if (currentStep == 2)
        {
            <div class="form-step">
                <h2>References</h2>

                @for (int i = 0; i < references.Count; i++)
                {
                    var index = i;
                    <div class="reference-card">
                        <div class="work-entry-header">
                            <h3>Reference @(index + 1)</h3>
                            @if (references.Count > 2)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>

                        <div class="form-group">
                            <label>Name *</label>
                            <input type="text" @bind="references[index].Name" class="form-control" />
                        </div>

                        <div class="form-group">
                            <label>Relationship *</label>
                            <input type="text" @bind="references[index].Relationship" class="form-control" />
                        </div>

                        <div class="form-row">
                            <div class="form-group">
                                <label>Email *</label>
                                <input type="email" @bind="references[index].Email" class="form-control" />
                            </div>

                            <div class="form-group">
                                <label>Phone *</label>
                                <input type="tel" @bind="references[index].Phone" class="form-control" />
                            </div>
                        </div>
                    </div>
                }

                @if (errors.ContainsKey("references"))
                {
                    <span class="error">@errors["references"]</span>
                }

                @if (references.Count < 3)
                {
                    <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
                }

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
                </div>
            </div>
        }

        <!-- Step 4: Cover Letter -->
        @if (currentStep == 3)
        {
            <div class="form-step">
                <h2>Cover Letter</h2>

                <div class="form-group">
                    <label for="coverLetter">Write your cover letter</label>
                    <textarea id="coverLetter" @bind="coverLetter" @bind:event="oninput"
                              class="form-control cover-letter-input" rows="12"
                              maxlength="2000"></textarea>
                    <div class="character-count">@coverLetter.Length / 2000 characters</div>
                </div>

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
                </div>
            </div>
        }

        <!-- Step 5: Review & Submit -->
        @if (currentStep == 4)
        {
            <div class="form-step">
                <h2>Review & Submit</h2>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <a href="javascript:void(0)" @onclick='() => NavigateToStep(0)'>Edit</a>
                    </div>
                    <dl>
                        <dt>Full Name</dt><dd>@fullName</dd>
                        <dt>Email</dt><dd>@email</dd>
                        <dt>Phone</dt><dd>@phone</dd>
                        <dt>Address</dt><dd>@address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <a href="javascript:void(0)" @onclick='() => NavigateToStep(1)'>Edit</a>
                    </div>
                    @foreach (var entry in workEntries)
                    {
                        <div class="review-work-entry">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                            <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p>@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <a href="javascript:void(0)" @onclick='() => NavigateToStep(2)'>Edit</a>
                    </div>
                    @foreach (var reference in references)
                    {
                        <div class="review-reference">
                            <strong>@reference.Name</strong> (@reference.Relationship)<br />
                            <span>@reference.Email | @reference.Phone</span>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <a href="javascript:void(0)" @onclick='() => NavigateToStep(3)'>Edit</a>
                    </div>
                    <p class="cover-letter-preview">@coverLetter</p>
                </div>

                @if (errors.ContainsKey("submit"))
                {
                    <div class="error">@errors["submit"]</div>
                }

                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary btn-submit" @onclick="SubmitApplication" disabled="@isSubmitting">
                        @if (isSubmitting)
                        {
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
            </div>
        }
    }
    else
    {
        <!-- Confirmation -->
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted Successfully!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <div class="application-id">@applicationId</div>
            <p>Please save this ID for your records.</p>
        </div>
    }
</div>

