@code {
    private readonly string[] stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
    private int currentStep = 0;
    private bool isSubmitted = false;
    private int applicationId = 0;
    private bool isValidating = false;
    private bool isSubmitting = false;
    private Dictionary<string, string> errors = new();

    // Step 1: Personal Info
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2: Work History
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string coverLetter = "";

    private string GetStepClass(int step)
    {
        if (step == currentStep) return "active";
        if (step < currentStep) return "completed";
        return "";
    }

    private void NavigateToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(fullName))
            errors["fullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(email))
            errors["email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(phone))
            errors["phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(address))
            errors["address"] = "Address is required.";

        if (errors.Count > 0) return;

        isValidating = true;
        StateHasChanged();

        try
        {
            var isEmailValid = await ApplicationService.ValidateEmailAsync(email);
            if (!isEmailValid)
            {
                errors["email"] = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        currentStep = 1;
    }

    private void NextFromWorkHistory()
    {
        errors.Clear();

        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == default)
            {
                errors["work"] = "Each position requires at least a company name, job title, and start date.";
                return;
            }
        }

        currentStep = 2;
    }

    private void NextFromReferences()
    {
        errors.Clear();

        foreach (var reference in references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship)
                || string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                errors["references"] = "All fields are required for each reference.";
                return;
            }
        }

        currentStep = 3;
    }

    private void NextFromCoverLetter()
    {
        currentStep = 4;
    }

    private void PreviousStep()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void AddWorkEntry()
    {
        workEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        errors.Clear();
        isSubmitting = true;
        StateHasChanged();

        try
        {
            var personal = new PersonalInfo(fullName, email, phone, address);
            var work = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? "")
            ).ToList());
            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            errors["submit"] = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

